import argparse,collections,hashlib,json
from pathlib import Path
P=Path(__file__).resolve().parents[1];W=P.parent
SHA=lambda p:hashlib.sha256(p.read_bytes()).hexdigest()
# Every part is declared explicitly. Missing fields never imply text/no diagram.
# Tuples: recipe slug, branch, part, kind, main WO locator, must-read givens,
# interpretation/response distinction, supplementary WO locators.
