def build():
 rows=[];files={}
 for slug,branch,part,kind,needle,givens,note,extra in DECLARATIONS:
  path='work-orders/WB8227-'+slug+'.md';p=W/path;text=p.read_text();lines=text.splitlines();files[path]=SHA(p)
  def locator(n):
   hits=[(i,line)for i,line in enumerate(lines,1)if n in line];assert hits,(path,n);i,line=hits[0]
   return dict(work_order_path=path,line=i,quote=line)
  primary=locator(needle);others=[locator(n)for n in extra]
  rows.append(dict(qualified_part_id='WB8227-'+slug+':'+branch+':'+part,recipe_id='WB8227-'+slug,branch_id=branch,part_id=part,kind=kind,given_representation=kind,must_read_givens=givens,source=primary,supplementary_sources=others,work_order_sha256=files[path],classification_basis='Current work-order declaration plus explicit per-part planner judgement; internal design evidence, not an official syllabus or observed-exam fact.',interpretation=note,learner_produced_response_is_not_given=True,geometric_diagram_given=(kind=='diagram')))
 assert len(rows)==len({r['qualified_part_id']for r in rows})==27
 pilot=json.loads((P/'pilot-design.json').read_text());expected={p['qualified_part_id']for r in pilot['recipes']for b in r['branches']for p in b['part_specs']};assert {r['qualified_part_id']for r in rows}==expected
 assert len(files)==9
 counts=collections.Counter(r['kind']for r in rows)
 assert set(counts)<=set(['text','graph','table','diagram'])
 return dict(subject='NSSCAS Mathematics 8227',syllabus_edition='NIED December 2020',owner='Vitalis',role='PLANNER',date='2026-11-24',status='D4 explicit supplied-representation declarations; exact-manifest approval pending',purpose='Close the complete given-representation denominator for the planning coverage receipt without interpreting absent canonical metadata as zero.',scope='Given information in the current 27 assessed part slots only. Learner-produced sketches, blank response frames and optional solution graphics are recorded separately and never counted as supplied geometric diagrams.',parts=rows,input_work_orders=files,input_pilot_design_sha256=SHA(P/'pilot-design.json'),counts=dict(parts=len(rows),known_representations=len(rows),unknown_representations=0,by_kind={k:counts.get(k,0)for k in ['text','graph','table','diagram']},given_geometric_diagram_parts=sum(r['geometric_diagram_given']for r in rows)),specific_resolutions=['Trapezium a/b are explicitly text in its work order; no supplied ordinate table appears in the question specification.','Trapezium c supplies only blank axes as a response frame. Part d uses the learner-produced sketch, not a given diagram.','Column vectors are symbolic text. Modulus and transformed-log inputs are function graphs, not spatial/geometric diagrams.','Gradient-target log branch supplies a stated gradient in text and explicitly forbids substituting a fake graph.'],limits='Author interpretation of declared designs only; does not verify a generated asset, visual marking capability, syllabus breadth or runtime UI.')

def md(d):
 lines=['# Given-representation register — NSSCAS Mathematics 8227 D4','','The 27 current part slots are explicitly classified from all nine work orders; missing canonical fields are never treated as zero. These are internal planner declarations, pending exact-manifest approval. Counts refer to supplied information, excluding learner-created responses, blank response frames and optional solutions.','','| Kind | Given part count |','|---|---:|']
 for kind,n in d['counts']['by_kind'].items():lines.append(f'| {kind} | {n} |')
 lines+=['',f"Known representations: {d['counts']['known_representations']}/27; unknown: {d['counts']['unknown_representations']}; supplied geometric-diagram parts: {d['counts']['given_geometric_diagram_parts']}.",'','| Part | Given kind | Must-read information | Work-order locator | Interpretation |','|---|---|---|---|---|']
 for row in d['parts']:
  cells=[row['qualified_part_id'],row['kind'],'; '.join(row['must_read_givens']),row['source']['work_order_path']+':'+str(row['source']['line']),row['interpretation']]
  lines.append('| '+' | '.join(x.replace('|','\\|')for x in cells)+' |')
 lines+=['','## Specific distinctions','']+['- '+x for x in d['specific_resolutions']]+['',d['limits'],'','Structured JSON includes the exact source lines, current work-order hashes, all additional part-specific locators and the current pilot-design hash. Rebuild/check with `planning/d4/build-given-representation-register.py` and `--check`.']
 return '\n'.join(lines)+'\n'
if __name__=='__main__':
 ap=argparse.ArgumentParser();ap.add_argument('--check',action='store_true');args=ap.parse_args();d=build();outputs={P/'d4/given-representation-register.json':json.dumps(d,indent=2,ensure_ascii=False)+'\n',P/'d4/given-representation-register.md':md(d)}
 for p,text in outputs.items():
  if args.check:assert p.read_text()==text,('stale explicit representation register',str(p))
  else:p.write_text(text)
 print(json.dumps(dict(status='pass',**d['counts']),indent=2))
